-- InstallScripts.command.lua: GENERATED by game/tools/build_install.js. Do not edit by hand;
-- edit the files in game/src and run `npm run build` in game/.
--
-- Paste into the Roblox Studio Command Bar (View > Command Bar) and press Enter, or let Claude
-- run it through the Roblox Studio MCP. It creates or updates every game script, then you save
-- the place. Safe to run again: scripts keep their instance and only get new Source.

local ChangeHistoryService = game:GetService("ChangeHistoryService")
local recording = nil
pcall(function() recording = ChangeHistoryService:TryBeginRecording("Install Steal a Beast scripts") end)
local created, updated = 0, 0

local function ensure(pathNames, className)
	local parent = game:GetService(pathNames[1])
	for i = 2, #pathNames do
		local name = pathNames[i]
		local child = parent:FindFirstChild(name)
		local wanted = (i == #pathNames) and className or nil
		if child and wanted and child.ClassName ~= wanted then
			-- wrong kind (for example a Folder where a ModuleScript belongs): replace it, keep its children
			local replacement = Instance.new(wanted)
			replacement.Name = name
			for _, grandchild in ipairs(child:GetChildren()) do grandchild.Parent = replacement end
			child:Destroy()
			replacement.Parent = parent
			child = replacement
			created = created + 1
		elseif not child then
			child = Instance.new(wanted or "Folder")
			child.Name = name
			child.Parent = parent
			if wanted then created = created + 1 end
		elseif wanted and child:IsA("LuaSourceContainer") then
			updated = updated + 1
		end
		parent = child
	end
	return parent
end

local function install(pathNames, className, source)
	local instance = ensure(pathNames, className)
	if source then instance.Source = source end
end

install({ "ReplicatedStorage", "Shared" }, "Folder", nil)

