install({ "ReplicatedStorage", "Shared", "NumberFormat" }, "ModuleScript", [=[
--[[
	NumberFormat  (ReplicatedStorage.Shared.NumberFormat)

	Short number text for the HUD, signs and shop: 950, 1.2K, 4.5M, 3.1B, 7T, 2.2Qa ...
	Lua 5.3-compatible Luau, so the tests can load it.
]]

local NumberFormat = {}

local SUFFIXES = { "K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No", "Dc" }

-- 1234 -> "1.2K", 1000000 -> "1M", 999 -> "999", 12.5 -> "12.5"
function NumberFormat.short(n)
	if n ~= n then
		return "0"
	end
	if n < 0 then
		return "-" .. NumberFormat.short(-n)
	end
	if n < 1000 then
		if n == math.floor(n) then
			return string.format("%d", n)
		end
		return (string.format("%.1f", n):gsub("%.0$", ""))
	end
	local index = 0
	while n >= 999.5 and index < #SUFFIXES do
		n = n / 1000
		index = index + 1
	end
	local text
	if n >= 100 then
		text = string.format("%d", math.floor(n + 0.5))
	else
		text = string.format("%.1f", n):gsub("%.0$", "")
	end
	return text .. SUFFIXES[index]
end

function NumberFormat.cash(n)
	return "$" .. NumberFormat.short(n)
end

-- 1234567 -> "1,234,567" (whole numbers only)
function NumberFormat.commas(n)
	local text = string.format("%d", math.floor(n))
	local out = text:reverse():gsub("(%d%d%d)", "%1,"):reverse()
	return (out:gsub("^(%-?),", "%1"))
end

-- Steal An Egg's counter style: whole numbers with commas ("$43,931"). Once the number
-- reaches 1,000,000 it switches to a suffix but keeps commas: 89,121,000,000 -> "89,121M".
function NumberFormat.commasShort(n)
	if n ~= n then
		return "0"
	end
	if n < 0 then
		return "-" .. NumberFormat.commasShort(-n)
	end
	local index = 0
	while n >= 1000000 and index < #SUFFIXES do
		n = n / 1000
		index = index + 1
	end
	if index > 0 then
		n = n * (1 + 1e-12) -- 89121 * 1000^8 / 1000^8 can come back as 89120.9999...
	end
	return NumberFormat.commas(n) .. (SUFFIXES[index] or "")
end

function NumberFormat.cashLong(n)
	return "$" .. NumberFormat.commasShort(n)
end

-- 75 -> "1:15"
function NumberFormat.clock(seconds)
	seconds = math.max(0, math.floor(seconds))
	if seconds >= 3600 then
		return string.format("%d:%02d:%02d", math.floor(seconds / 3600), math.floor(seconds / 60) % 60, seconds % 60)
	end
	return string.format("%d:%02d", math.floor(seconds / 60), seconds % 60)
end

return NumberFormat
]=])

install({ "ServerScriptService", "Main" }, "Script", [=[
--[[
	Main: starts the gameplay services in order. Each service lives in ./Services and has a
	start() function. DataService starts last, so every other service is already listening
	when the first save loads.
]]

local Services = script.Parent:WaitForChild("Services")

local ORDER = { "RanchService", "SpeedService", "ShopService", "StatsService", "NameTagService", "DevService", "DataService" }

for _, name in ipairs(ORDER) do
	local ok, err = pcall(function()
		require(Services:WaitForChild(name)).start()
	end)
	if not ok then
		warn("[Main] " .. name .. " failed to start: " .. tostring(err))
	end
end

print("[Main] Steal a Beast server started")
]=])

install({ "ServerScriptService", "Services" }, "Folder", nil)

install({ "ServerScriptService", "Services", "DataService" }, "ModuleScript", [=[
--[[
	DataService: loads, holds and saves every player's save table.

	* One DataStore key per player ("u_<UserId>"), written only with UpdateAsync.
	* Session lock: the save records which server owns it (JobId + time). Another server that
	  joins while the lock is fresh waits and retries; a lock older than
	  GameConfig.Data.SessionLockSeconds is treated as abandoned (that server crashed).
	* Autosave every GameConfig.Data.AutosaveSeconds, a save on leave and on shutdown.
	* In Studio without "Enable Studio Access to API Services", the DataStore calls fail;
	  the player then plays on a fresh in-memory save that is never written (a warning says so).

	Other services read and change data through DataService.get(player) and then call
	DataService.changed(player) so the HUD attributes refresh.
]]

local DataStoreService = game:GetService("DataStoreService")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local GameConfig = require(Shared:WaitForChild("GameConfig"))
local Economy = require(Shared:WaitForChild("Economy"))

local DataService = {}

local sessions = {}       -- [player] = { data =, saveable =, dirty = }
local loadedCallbacks = {}
local changedCallbacks = {}
local store = nil
local jobId = game.JobId ~= "" and game.JobId or ("studio-" .. tostring(math.random(1, 1e9)))

local function keyFor(player)
	return "u_" .. player.UserId
end

local function tryStore()
	local ok, result = pcall(function()
		return DataStoreService:GetDataStore(GameConfig.Data.StoreName)
	end)
	if ok then
		return result
	end
	warn("[DataService] DataStores unavailable, progress will NOT be saved: " .. tostring(result))
	return nil
end

-- Returns data, saveable. Takes the session lock.
local function load(player)
	if not store then
		return Economy.newData(), false
	end
	local key = keyFor(player)
	for attempt = 1, GameConfig.Data.LoadRetries do
		local lockedByOther = false
		local ok, result = pcall(function()
			return store:UpdateAsync(key, function(saved)
				saved = type(saved) == "table" and saved or { Data = nil }
				local lock = saved.Lock
				-- Studio is a single session, so a lock there is always left over from the last playtest
				if lock and lock.JobId ~= jobId and os.time() - (lock.Time or 0) < GameConfig.Data.SessionLockSeconds
					and attempt < GameConfig.Data.LoadRetries and not RunService:IsStudio() then
					lockedByOther = true
					return nil -- leave the save untouched
				end
				saved.Lock = { JobId = jobId, Time = os.time() }
				return saved
			end)
		end)
		if ok and not lockedByOther then
			local data = Economy.reconcile(result and result.Data)
			return data, true
		end
		if not ok then
			warn(string.format("[DataService] load %s failed (try %d): %s", player.Name, attempt, tostring(result)))
			if string.find(tostring(result), "API", 1, true) or string.find(tostring(result), "Studio", 1, true) then
				warn("[DataService] Studio has no API access: playing on an unsaved session. "
					.. "Turn on Game Settings > Security > Enable Studio Access to API Services to test saving.")
				return Economy.newData(), false
			end
		end
		task.wait(attempt * 2)
		if not player.Parent then
			return nil, false
		end
	end
	warn("[DataService] could not load " .. player.Name .. "; using an unsaved session")
	return Economy.newData(), false
end

local function save(player, release)
	local session = sessions[player]
	if not session or not session.saveable or not store then
		return true
	end
	local snapshot = Economy.serialize(session.data)
	local ok, err = pcall(function()
		store:UpdateAsync(keyFor(player), function(saved)
			saved = type(saved) == "table" and saved or {}
			if saved.Lock and saved.Lock.JobId ~= jobId then
				return nil -- another server took over; never overwrite its newer data
			end
			saved.Data = snapshot
			saved.Lock = (not release) and { JobId = jobId, Time = os.time() } or nil
			return saved
		end)
	end)
	if not ok then
		warn("[DataService] save " .. player.Name .. " failed: " .. tostring(err))
	end
	return ok
end

function DataService.get(player)
	local session = sessions[player]
	return session and session.data or nil
end

function DataService.isLoaded(player)
	return sessions[player] ~= nil
end

-- fn(player, data) runs once a player's data is loaded (now, if it already is).
function DataService.onLoaded(fn)
	table.insert(loadedCallbacks, fn)
	for player, session in pairs(sessions) do
		task.spawn(fn, player, session.data)
	end
end

-- fn(player, data) runs after any service changes a player's data.
function DataService.onChanged(fn)
	table.insert(changedCallbacks, fn)
end

function DataService.changed(player)
	local session = sessions[player]
	if not session then
		return
	end
	for _, fn in ipairs(changedCallbacks) do
		fn(player, session.data)
	end
end

-- Runs fn(data) for a loaded player, then fires changed. Returns what fn returns.
function DataService.update(player, fn)
	local data = DataService.get(player)
	if not data then
		return false, "Still loading"
	end
	local a, b = fn(data)
	DataService.changed(player)
	return a, b
end

local function onPlayerAdded(player)
	local data, saveable = load(player)
	if not data or not player.Parent then
		return
	end
	sessions[player] = { data = data, saveable = saveable }
	for _, fn in ipairs(loadedCallbacks) do
		task.spawn(fn, player, data)
	end
	DataService.changed(player)
end

local function onPlayerRemoving(player)
	if sessions[player] then
		save(player, true)
		sessions[player] = nil
	end
end

function DataService.start()
	store = tryStore()
	Players.PlayerAdded:Connect(onPlayerAdded)
	Players.PlayerRemoving:Connect(onPlayerRemoving)
	for _, player in ipairs(Players:GetPlayers()) do
		task.spawn(onPlayerAdded, player)
	end

	task.spawn(function()
		while true do
			task.wait(GameConfig.Data.AutosaveSeconds)
			for player in pairs(sessions) do
				task.spawn(save, player, false)
			end
		end
	end)

	game:BindToClose(function()
		if RunService:IsStudio() and not store then
			return
		end
		local pending = 0
		for player in pairs(sessions) do
			pending = pending + 1
			task.spawn(function()
				save(player, true)
				pending = pending - 1
			end)
		end
		local started = os.clock()
		while pending > 0 and os.clock() - started < 25 do
			task.wait(0.1)
		end
	end)
end

return DataService
]=])

install({ "ServerScriptService", "Services", "DevService" }, "ModuleScript", [=[
--[[
	DevService: test helpers that exist ONLY in Studio (never in a live server).

	Creates ServerStorage.DevCommands (a BindableFunction). While playtesting, switch the
	Command Bar to the Server and run, for example:

	  game.ServerStorage.DevCommands:Invoke("cash", 1e6)                 -- +$1M for every player
	  game.ServerStorage.DevCommands:Invoke("speed", 10000)              -- +10K Speed
	  game.ServerStorage.DevCommands:Invoke("beast", "GoldenGoose", 12, "Golden")  -- id, kg, mutation
	  game.ServerStorage.DevCommands:Invoke("reset")                     -- fresh save (not written in Studio)

	An optional last argument picks one player by name; otherwise every player is changed.
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ServerStorage = game:GetService("ServerStorage")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Economy = require(ReplicatedStorage:WaitForChild("Shared"):WaitForChild("Economy"))

local Services = script.Parent
local DataService = require(Services:WaitForChild("DataService"))

local DevService = {}

local function targets(name)
	if type(name) == "string" then
		local player = Players:FindFirstChild(name)
		return player and { player } or {}
	end
	return Players:GetPlayers()
end

local COMMANDS = {
	cash = function(data, amount)
		data.Cash = data.Cash + (tonumber(amount) or 0)
	end,
	speed = function(data, amount)
		data.Speed = data.Speed + (tonumber(amount) or 0)
	end,
	beast = function(data, id, kg, mutation)
		local slot, reason = Economy.addBeast(data, { id = id, kg = tonumber(kg), mutation = mutation })
		return slot ~= nil, reason
	end,
	reset = function(data)
		local fresh = Economy.newData()
		for key in pairs(data) do
			data[key] = nil
		end
		for key, value in pairs(fresh) do
			data[key] = value
		end
	end,
}

-- The player name is the argument after the command's own arguments.
local ARG_COUNT = { cash = 1, speed = 1, beast = 3, reset = 0 }

function DevService.start()
	if not RunService:IsStudio() then
		return
	end
	local fn = ServerStorage:FindFirstChild("DevCommands") or Instance.new("BindableFunction")
	fn.Name = "DevCommands"
	fn.OnInvoke = function(command, ...)
		local handler = COMMANDS[command]
		if not handler then
			return "unknown command; try cash, speed, beast, reset"
		end
		local args = table.pack(...)
		local changed = {}
		for _, player in ipairs(targets(args[ARG_COUNT[command] + 1])) do
			local ok, reason = DataService.update(player, function(data)
				return handler(data, table.unpack(args, 1, ARG_COUNT[command]))
			end)
			table.insert(changed, player.Name .. (ok == false and (" (" .. tostring(reason) .. ")") or ""))
		end
		return command .. ": " .. (#changed > 0 and table.concat(changed, ", ") or "no players")
	end
	fn.Parent = ServerStorage
end

return DevService
]=])

install({ "ServerScriptService", "Services", "MapUtil" }, "ModuleScript", [=[
--[[
	MapUtil: finds the built map (workspace.Map, made by tools/BuildMap.command.lua) and
	has the small helpers every service needs: the zone test from MAP_SPEC section 3.4,
	sign text and the runtime folders.
]]

local CollectionService = game:GetService("CollectionService")

local MapUtil = {}

function MapUtil.waitForMap()
	local map = workspace:FindFirstChild("Map")
	if not map then
		warn("[MapUtil] workspace.Map is missing. Build it first: paste game/tools/BuildMap.command.lua "
			.. "into the Studio Command Bar (see game/README.md), then save the place.")
		map = workspace:WaitForChild("Map")
	end
	return map
end

-- True when pos is inside the part's box (works for rotated parts). pad grows the box.
function MapUtil.inBox(part, pos, pad)
	local p = part.CFrame:PointToObjectSpace(pos)
	local h = part.Size / 2
	pad = pad or Vector3.new(0, 0, 0)
	return math.abs(p.X) <= h.X + pad.X and math.abs(p.Y) <= h.Y + pad.Y and math.abs(p.Z) <= h.Z + pad.Z
end

function MapUtil.inAnyTagged(tag, pos)
	for _, part in ipairs(CollectionService:GetTagged(tag)) do
		if part:IsA("BasePart") and MapUtil.inBox(part, pos) then
			return part
		end
	end
	return nil
end

-- Sets the text of Line1, Line2 ... in a SurfaceGui or BillboardGui built by MapBuilder.
function MapUtil.setLines(gui, lines)
	if not gui then
		return
	end
	for i, text in ipairs(lines) do
		local label = gui:FindFirstChild("Line" .. i)
		if label then
			label.Text = text
		end
	end
end

function MapUtil.runtimeFolder(name)
	local runtime = workspace:FindFirstChild("Runtime")
	if not runtime then
		runtime = Instance.new("Folder")
		runtime.Name = "Runtime"
		runtime.Parent = workspace
	end
	local folder = runtime:FindFirstChild(name)
	if not folder then
		folder = Instance.new("Folder")
		folder.Name = name
		folder.Parent = runtime
	end
	return folder
end

function MapUtil.rootPart(player)
	local character = player.Character
	return character and character:FindFirstChild("HumanoidRootPart")
end

function MapUtil.humanoid(player)
	local character = player.Character
	return character and character:FindFirstChildOfClass("Humanoid")
end

return MapUtil
]=])

install({ "ServerScriptService", "Services", "NameTagService" }, "ModuleScript", [=[
--[[
	NameTagService: Steal An Egg's player tag, a round headshot with the username under it,
	floating over every player's head. It replaces Roblox's default name display.
]]

local Players = game:GetService("Players")

local NameTagService = {}

local FONT = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Heavy, Enum.FontStyle.Normal)

local function addTag(player, character)
	local head = character:WaitForChild("Head", 10)
	local humanoid = character:WaitForChild("Humanoid", 10)
	if not head or not humanoid then
		return
	end
	humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None

	local tag = Instance.new("BillboardGui")
	tag.Name = "NameTag"
	tag.Size = UDim2.new(5, 0, 3.4, 0)
	tag.StudsOffset = Vector3.new(0, 3.6, 0)
	tag.MaxDistance = 120
	tag.LightInfluence = 0
	tag.Adornee = head

	local photo = Instance.new("ImageLabel")
	photo.Name = "Headshot"
	photo.BackgroundColor3 = Color3.fromRGB(70, 70, 76)
	photo.Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150"
	photo.AnchorPoint = Vector2.new(0.5, 0)
	photo.Position = UDim2.new(0.5, 0, 0, 0)
	photo.Size = UDim2.new(0.66, 0, 0.66, 0)
	photo.SizeConstraint = Enum.SizeConstraint.RelativeYY
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0.5, 0)
	corner.Parent = photo
	local ring = Instance.new("UIStroke")
	ring.Thickness = 2
	ring.Color = Color3.new(0, 0, 0)
	ring.Parent = photo
	photo.Parent = tag

	local name = Instance.new("TextLabel")
	name.Name = "Username"
	name.BackgroundTransparency = 1
	name.Position = UDim2.new(0, 0, 0.68, 0)
	name.Size = UDim2.new(1, 0, 0.3, 0)
	name.FontFace = FONT
	name.Text = player.Name
	name.TextScaled = true
	name.TextColor3 = Color3.new(1, 1, 1)
	name.TextStrokeColor3 = Color3.new(0, 0, 0)
	name.TextStrokeTransparency = 0
	name.Parent = tag

	tag.Parent = head
end

function NameTagService.start()
	local function watch(player)
		player.CharacterAdded:Connect(function(character)
			addTag(player, character)
		end)
		if player.Character then
			task.spawn(addTag, player, player.Character)
		end
	end
	Players.PlayerAdded:Connect(watch)
	for _, player in ipairs(Players:GetPlayers()) do
		watch(player)
	end
end

return NameTagService
]=])

install({ "ServerScriptService", "Services", "RanchService" }, "ModuleScript", [=[
--[[
	RanchService: the 7 ranch plots (MAP_SPEC section 5) and the idle income.

	* Gives each joining player a random free plot (MAP_SPEC 5.1: random, so the first to join
	  doesn't always get the plot nearest the gate), writes their name on the OwnerSign and
	  spawns them on their PlotSpawn, facing the street.
	* Shows the pen: unlocks slot pads up to the player's pen size (creating Slot11..Slot19 on
	  upgrades) and puts a placeholder beast with a name tag on every filled slot.
	* Pays pen income every GameConfig.Pen.IncomeTickSeconds.
	* Frees the plot again when the player leaves.

	The beast models are simple placeholders (a body, a head and a tag) until the real
	beast models exist; HerdService will reuse makeBeastModel for herds and towing.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local GameConfig = require(Shared:WaitForChild("GameConfig"))
local AreasConfig = require(Shared:WaitForChild("AreasConfig"))
local Economy = require(Shared:WaitForChild("Economy"))
local NumberFormat = require(Shared:WaitForChild("NumberFormat"))

local Services = script.Parent
local DataService = require(Services:WaitForChild("DataService"))
local MapUtil = require(Services:WaitForChild("MapUtil"))
local Remotes = require(Services:WaitForChild("Remotes"))

local RanchService = {}

local plots = {}          -- [plotIndex] = Plot model
local owners = {}         -- [plotIndex] = player
local plotOf = {}         -- [player] = plotIndex
local shown = {}          -- [player] = { penSlots =, beasts = { [slot] = key }, tier = }

local MUTATION_COLORS = {
	Silver = Color3.fromRGB(215, 222, 230),
	Golden = Color3.fromRGB(255, 200, 40),
	Rainbow = Color3.fromRGB(255, 90, 200),
}

local function rgb(t)
	return Color3.fromRGB(t[1], t[2], t[3])
end

----------------------------------------------------------------------------------------------
-- Beast placeholder model
----------------------------------------------------------------------------------------------
-- Montserrat Black (Roblox's Gotham family), the font Steal An Egg uses everywhere
local TAG_FONT = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Heavy, Enum.FontStyle.Normal)

local RAINBOW = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 60, 60)),
	ColorSequenceKeypoint.new(0.2, Color3.fromRGB(255, 160, 30)),
	ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 240, 60)),
	ColorSequenceKeypoint.new(0.6, Color3.fromRGB(80, 230, 90)),
	ColorSequenceKeypoint.new(0.8, Color3.fromRGB(60, 170, 255)),
	ColorSequenceKeypoint.new(1, Color3.fromRGB(190, 80, 255)),
})

-- Name colours for mutated beasts (white on top, the coat colour at the bottom)
local MUTATION_TEXT = {
	Silver = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(190, 200, 215)),
	Golden = ColorSequence.new(Color3.fromRGB(255, 244, 130), Color3.fromRGB(255, 186, 10)),
	Rainbow = RAINBOW,
}

local function gradientOn(label, sequence, rotation)
	local gradient = Instance.new("UIGradient")
	gradient.Color = sequence
	gradient.Rotation = rotation
	gradient.Parent = label
	return gradient
end

local function tagLabel(parent, name, text, color, y, h)
	local label = Instance.new("TextLabel")
	label.Name = name
	label.BackgroundTransparency = 1
	label.Size = UDim2.new(1, 0, h, 0)
	label.Position = UDim2.new(0, 0, y, 0)
	label.FontFace = TAG_FONT
	label.TextScaled = true
	label.Text = text
	label.TextColor3 = color
	label.TextStrokeColor3 = Color3.new(0, 0, 0)
	label.TextStrokeTransparency = 0
	label.Parent = parent
	return label
end

-- beast = { id, kg, mutation }. Returns a Model whose pivot is at its feet.
function RanchService.makeBeastModel(beast)
	local info = Economy.Beasts[beast.id]
	local rarity = Economy.Rarities[info.rarity]
	-- Size grows slowly with weight: 2 studs for a 1 kg owl, about 9 for a 2,500 kg wyrm
	local size = math.clamp(2 + 2 * math.log(1 + beast.kg, 10), 2, 14)
	local coat = MUTATION_COLORS[beast.mutation] or rgb(rarity.color)

	local model = Instance.new("Model")
	model.Name = info.name

	local body = Instance.new("Part")
	body.Name = "Body"
	body.Shape = Enum.PartType.Ball
	body.Size = Vector3.new(size, size, size)
	body.Color = coat
	body.Material = beast.mutation == "None" and Enum.Material.SmoothPlastic or Enum.Material.Foil
	body.Anchored = true
	body.CanCollide = false
	body.CanTouch = false
	body.CFrame = CFrame.new(0, size / 2, 0)
	body.Parent = model

	local head = Instance.new("Part")
	head.Name = "Head"
	head.Shape = Enum.PartType.Ball
	head.Size = Vector3.new(size * 0.55, size * 0.55, size * 0.55)
	head.Color = coat
	head.Material = body.Material
	head.Anchored = true
	head.CanCollide = false
	head.CanTouch = false
	head.CFrame = CFrame.new(0, size * 0.85, -size * 0.45)
	head.Parent = model
	pcall(function()
		body.CollisionGroup = "Beasts"
		head.CollisionGroup = "Beasts"
	end)

	local tag = Instance.new("BillboardGui")
	tag.Name = "BeastTag"
	tag.Size = UDim2.new(8, 0, 4, 0)
	tag.StudsOffsetWorldSpace = Vector3.new(0, size + 3, 0)
	tag.MaxDistance = 90
	tag.LightInfluence = 0
	-- Steal An Egg's pet label (screenshot 2026-10-20): rarity on top ("Common"), then the name
	-- ("Golden Dog", in the mutation's colour), then the green "$11/s". Our weight line goes last.
	local rarityLabel = tagLabel(tag, "Rarity", info.rarity, Color3.new(1, 1, 1), 0, 0.26)
	if rarity.rainbowText then
		gradientOn(rarityLabel, RAINBOW, 0)
	else
		gradientOn(rarityLabel, ColorSequence.new(rgb(rarity.color):Lerp(Color3.new(1, 1, 1), 0.55), rgb(rarity.color)), 90)
	end
	local nameText = info.name
	if beast.mutation ~= "None" then
		nameText = beast.mutation .. " " .. info.name
	end
	local nameLabel = tagLabel(tag, "BeastName", nameText, Color3.new(1, 1, 1), 0.26, 0.26)
	if MUTATION_TEXT[beast.mutation] then
		gradientOn(nameLabel, MUTATION_TEXT[beast.mutation], beast.mutation == "Rainbow" and 0 or 90)
	end
	tagLabel(tag, "Income", NumberFormat.cashLong(Economy.beastIncome(beast)) .. "/s", Color3.fromRGB(24, 255, 24), 0.52, 0.3)
	tagLabel(tag, "Kg", NumberFormat.commas(beast.kg) .. " kg", Color3.fromRGB(235, 235, 235), 0.83, 0.17)
	model:SetAttribute("Income", Economy.beastIncome(beast))
	tag.Parent = body

	model.PrimaryPart = body
	model.WorldPivot = CFrame.new()
	return model
end

----------------------------------------------------------------------------------------------
-- Plot helpers
----------------------------------------------------------------------------------------------
local function ownerSign(plot)
	local gate = plot:FindFirstChild("Gate")
	local sign = gate and gate:FindFirstChild("OwnerSign")
	return sign and sign:FindFirstChild("SignFront")
end

local function setOwnerSign(plot, player)
	local gui = ownerSign(plot)
	if not gui then
		return
	end
	local line = gui:FindFirstChild("Line1")
	local headshot = gui:FindFirstChild("Headshot")
	if player then
		if line then
			line.Text = player.DisplayName .. "'s Ranch"
			line.Position = UDim2.new(0.2, 0, line.Position.Y.Scale, 0)
			line.Size = UDim2.new(0.78, 0, line.Size.Y.Scale, 0)
		end
		if headshot then
			local ok, image = pcall(function()
				return Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
			end)
			headshot.Image = ok and image or ""
			headshot.Visible = ok
		end
	else
		if line then
			line.Text = "FREE RANCH"
			line.Position = UDim2.new(0.03, 0, line.Position.Y.Scale, 0)
			line.Size = UDim2.new(0.94, 0, line.Size.Y.Scale, 0)
		end
		if headshot then
			headshot.Visible = false
			headshot.Image = ""
		end
	end
end

local function slotPad(plot, slot)
	local pen = plot:FindFirstChild("Pen")
	return pen and pen:FindFirstChild(string.format("Slot%02d", slot))
end

-- Pads 11..19 are not built with the map; clone Slot01 and move it to its layout spot.
local function ensurePad(plot, slot)
	local pad = slotPad(plot, slot)
	if pad then
		return pad
	end
	local first = slotPad(plot, 1)
	local layout = AreasConfig.Plots.SlotLayout
	if not first or not layout[slot] then
		return nil
	end
	pad = first:Clone()
	pad.Name = string.format("Slot%02d", slot)
	local dx = layout[slot][1] - layout[1][1]
	local dz = layout[slot][2] - layout[1][2]
	pad.CFrame = first.CFrame * CFrame.new(dx, 0, dz)
	pad:SetAttribute("SlotIndex", slot)
	pad.Parent = first.Parent
	return pad
end

local function styleSlot(pad, active)
	pad:SetAttribute("Active", active)
	pad.Material = active and Enum.Material.Sand or Enum.Material.SmoothPlastic
	pad.Color = active and Color3.fromRGB(222, 196, 120) or Color3.fromRGB(120, 120, 120)
	pad.Transparency = active and 0 or 0.5
	local label = pad:FindFirstChild("Label")
	if active and label then
		label:Destroy()
	elseif not active and not label then
		local gui = Instance.new("BillboardGui")
		gui.Name = "Label"
		gui.Size = UDim2.new(6, 0, 1.6, 0)
		gui.StudsOffset = Vector3.new(0, 2, 0)
		gui.MaxDistance = 80
		gui.LightInfluence = 0
		tagLabel(gui, "Line1", "LOCKED", Color3.fromRGB(255, 255, 255), 0, 1)
		gui.Parent = pad
	end
end

local function updateTreadmillSign(plot, tier)
	local treadmill = plot:FindFirstChild("Treadmill")
	local base = treadmill and treadmill:FindFirstChild("Base")
	if not base then
		return
	end
	treadmill:SetAttribute("Tier", tier)
	local info = GameConfig.Treadmill.Tiers[tier]
	MapUtil.setLines(base:FindFirstChild("TierDisplay"), {
		string.upper(info.name) .. " \u{00B7} TIER " .. tier,
		"+" .. NumberFormat.short(info.speedPerStep) .. " / step",
	})
end

-- The Upgrade Pen sign by the gate (MAP_SPEC section 13): level, next level and price.
local function updateUpgradeSign(plot, data)
	local model = plot:FindFirstChild("UpgradeSign")
	local board = model and model:FindFirstChild("Board")
	local gui = board and board:FindFirstChild("SignFront")
	if not gui then
		return
	end
	local level = data and data.PenLevel or 1
	local price = (data and Economy.penUpgradePrice(data)) or (not data and GameConfig.Pen.UpgradePrices[1]) or nil
	local levelLine, priceLine = gui:FindFirstChild("Line2"), gui:FindFirstChild("Line3")
	if levelLine then
		levelLine.TextColor3 = Color3.fromRGB(90, 255, 90)
		levelLine.Text = price and string.format("Level %d > Level %d", level, level + 1) or string.format("Level %d (MAX)", level)
	end
	if priceLine then
		priceLine.Text = price and NumberFormat.cash(price) or "MAXED"
		local back = gui:FindFirstChild("PriceBack")
		if not back then
			back = Instance.new("Frame")
			back.Name = "PriceBack"
			back.BackgroundColor3 = Color3.fromRGB(110, 222, 34)
			back.BorderSizePixel = 0
			back.AnchorPoint = Vector2.new(0.5, 0)
			back.Position = UDim2.new(0.5, 0, priceLine.Position.Y.Scale, 0)
			back.Size = UDim2.new(0.5, 0, priceLine.Size.Y.Scale, 0)
			back.ZIndex = 0
			local corner = Instance.new("UICorner")
			corner.CornerRadius = UDim.new(0.2, 0)
			corner.Parent = back
			local border = Instance.new("UIStroke")
			border.Thickness = 2
			border.Color = Color3.fromRGB(30, 70, 12)
			border.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			border.Parent = back
			back.Parent = gui
			priceLine.ZIndex = 2
		end
		back.BackgroundColor3 = price and Color3.fromRGB(110, 222, 34) or Color3.fromRGB(110, 110, 116)
	end
end

-- Adds the "Upgrade Pen" prompt; only the plot's owner can use it.
local function addUpgradePrompt(plot, index)
	local model = plot:FindFirstChild("UpgradeSign")
	local board = model and model:FindFirstChild("Board")
	if not board or board:FindFirstChild("UpgradePrompt") then
		return
	end
	local prompt = Instance.new("ProximityPrompt")
	prompt.Name = "UpgradePrompt"
	prompt.ActionText = "Upgrade"
	prompt.ObjectText = "Pen"
	prompt.HoldDuration = 0
	prompt.MaxActivationDistance = 12
	prompt.RequiresLineOfSight = false
	prompt.Parent = board
	prompt.Triggered:Connect(function(player)
		if plotOf[player] ~= index then
			Remotes.notify(player, "That's not your ranch!", "bad")
			return
		end
		local ok, reason = DataService.update(player, function(data)
			return Economy.buyPenSlot(data)
		end)
		local data = DataService.get(player)
		if ok and data then
			Remotes.notify(player, string.format("Pen upgraded: %d slots", Economy.penSlots(data)), "good")
		else
			Remotes.notify(player, reason or "Can't upgrade", "bad")
		end
	end)
end

local function beastFolder(player)
	local name = "Plot" .. tostring(plotOf[player])
	local root = MapUtil.runtimeFolder("PenBeasts")
	local folder = root:FindFirstChild(name)
	if not folder then
		folder = Instance.new("Folder")
		folder.Name = name
		folder.Parent = root
	end
	return folder
end

-- Brings the plot's pads, beasts and treadmill sign in line with the save data.
local function refreshPlot(player, data)
	local index = plotOf[player]
	local plot = index and plots[index]
	if not plot then
		return
	end
	local state = shown[player]
	local slots = Economy.penSlots(data)

	if state.penSlots ~= slots then
		local count = math.max(slots, AreasConfig.Plots.PenBuiltSlots)
		for slot = 1, count do
			local pad = ensurePad(plot, slot)
			if pad then
				styleSlot(pad, slot <= slots)
			end
		end
		plot:SetAttribute("PenLevel", data.PenLevel)
		updateUpgradeSign(plot, data)
		state.penSlots = slots
	end

	local folder = beastFolder(player)
	for slot = 1, AreasConfig.Plots.PenMaxSlots do
		local beast = data.Pen[slot]
		local key = beast and (beast.id .. "|" .. beast.kg .. "|" .. beast.mutation) or nil
		if state.beasts[slot] ~= key then
			local old = folder:FindFirstChild("Slot" .. slot)
			if old then
				old:Destroy()
			end
			local pad = slotPad(plot, slot)
			if beast and pad then
				local model = RanchService.makeBeastModel(beast)
				model.Name = "Slot" .. slot
				local pivot = pad:FindFirstChild("BeastPivot")
				local at = pivot and pivot.WorldCFrame or pad.CFrame
				model:PivotTo(at)
				model.Parent = folder
			end
			if pad then
				pad:SetAttribute("Occupied", beast ~= nil)
			end
			state.beasts[slot] = key
		end
	end

	if state.tier ~= data.TreadmillTier then
		updateTreadmillSign(plot, data.TreadmillTier)
		state.tier = data.TreadmillTier
	end
end

local function spawnAtPlot(player, character)
	local index = plotOf[player]
	local plot = index and plots[index]
	local spawnPart = plot and plot:FindFirstChild("PlotSpawn")
	if not spawnPart then
		return
	end
	local root = character:WaitForChild("HumanoidRootPart", 10)
	if not root then
		return
	end
	task.wait() -- let the default spawn finish, or it overrides us
	character:PivotTo(spawnPart.CFrame * CFrame.new(0, 3.5, 0))
end

local function assignPlot(player)
	local free = {}
	for index in pairs(plots) do
		if not owners[index] then
			table.insert(free, index)
		end
	end
	if #free == 0 then
		warn("[RanchService] no free plot for " .. player.Name)
		return nil
	end
	local index = free[math.random(1, #free)]
	owners[index] = player
	plotOf[player] = index
	shown[player] = { beasts = {} }
	local plot = plots[index]
	plot:SetAttribute("OwnerUserId", player.UserId)
	player:SetAttribute("PlotIndex", index)
	task.spawn(setOwnerSign, plot, player)
	return index
end

local function releasePlot(player)
	local index = plotOf[player]
	if not index then
		return
	end
	local plot = plots[index]
	local folder = MapUtil.runtimeFolder("PenBeasts"):FindFirstChild("Plot" .. index)
	if folder then
		folder:Destroy()
	end
	for slot = 1, AreasConfig.Plots.PenMaxSlots do
		local pad = slotPad(plot, slot)
		if pad then
			if slot > AreasConfig.Plots.PenBuiltSlots then
				pad:Destroy()
			else
				pad:SetAttribute("Occupied", false)
				styleSlot(pad, slot <= AreasConfig.Plots.PenStartSlots)
			end
		end
	end
	plot:SetAttribute("OwnerUserId", 0)
	plot:SetAttribute("PenLevel", 1)
	updateUpgradeSign(plot, nil)
	updateTreadmillSign(plot, 1)
	setOwnerSign(plot, nil)
	owners[index] = nil
	plotOf[player] = nil
	shown[player] = nil
end

----------------------------------------------------------------------------------------------
-- Public
----------------------------------------------------------------------------------------------
function RanchService.plotIndex(player)
	return plotOf[player]
end

function RanchService.plot(player)
	local index = plotOf[player]
	return index and plots[index] or nil
end

function RanchService.start()
	local map = MapUtil.waitForMap()
	for _, plot in ipairs(map:WaitForChild("Plots"):GetChildren()) do
		local index = plot:GetAttribute("PlotIndex")
		if index then
			plots[index] = plot
			updateUpgradeSign(plot, nil)
			addUpgradePrompt(plot, index)
		end
	end

	local function onPlayer(player)
		if not assignPlot(player) then
			return
		end
		local data = DataService.get(player)
		if data then
			refreshPlot(player, data)
		end
		player.CharacterAdded:Connect(function(character)
			spawnAtPlot(player, character)
		end)
		if player.Character then
			task.spawn(spawnAtPlot, player, player.Character)
		end
	end
	Players.PlayerAdded:Connect(onPlayer)
	for _, player in ipairs(Players:GetPlayers()) do
		onPlayer(player)
	end
	Players.PlayerRemoving:Connect(releasePlot)

	DataService.onChanged(function(player, data)
		if shown[player] then
			refreshPlot(player, data)
		end
	end)

	-- Income tick
	task.spawn(function()
		local interval = GameConfig.Pen.IncomeTickSeconds
		while true do
			task.wait(interval)
			for _, player in ipairs(Players:GetPlayers()) do
				local data = DataService.get(player)
				if data and next(data.Pen) then
					Economy.payIncome(data, interval, RanchService.incomeMultiplier(player))
					DataService.changed(player)
				end
			end
		end
	end)
end

-- 2x Money pass and events plug in here later (MarketService, EventService).
function RanchService.incomeMultiplier(player)
	return 1
end

return RanchService
]=])

install({ "ServerScriptService", "Services", "Remotes" }, "ModuleScript", [=[
--[[
	Remotes: creates ReplicatedStorage.Remotes. The client only ever sends intents; the
	server checks everything (Systems and Scripts: "the server decides everything").

	  Notify         RemoteEvent     server -> client   (text, kind)   kind = "info" | "good" | "bad"
	  TreadmillStep  RemoteEvent     server -> client   (gain, spurMultiplier)
	  Shop           RemoteFunction  client -> server   (action, arg) -> ok, message
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Remotes = {}

local DEFINITIONS = {
	Notify = "RemoteEvent",
	TreadmillStep = "RemoteEvent",
	Shop = "RemoteFunction",
}

local folder = ReplicatedStorage:FindFirstChild("Remotes")
if not folder then
	folder = Instance.new("Folder")
	folder.Name = "Remotes"
	folder.Parent = ReplicatedStorage
end

for name, className in pairs(DEFINITIONS) do
	local remote = folder:FindFirstChild(name)
	if not remote then
		remote = Instance.new(className)
		remote.Name = name
		remote.Parent = folder
