local function zoneSpec(name, tagName, size, pos)
	local attrs = nil
	if tagName == "SafeZone" then
		attrs = { ZoneName = name }
	end
	return { "Block", size, pos, nil, nil, { name = name, invisible = true, query = true, tags = { tagName }, attrs = attrs } }
end

