	for _, x in ipairs({ 148, 220, 292 }) do
		for _, z in ipairs({ 60, 100, -60, -100 }) do
			newPart(ctx, { "VCyl", { 3, 2.4 }, { x, 1.5, z }, "Wood", { 130, 90, 56 }, { name = "Barrel", decor = true } }, I, barrels)
		end
	end

	return town
end

