local function refresh()
	local cash = player:GetAttribute("Cash") or 0
	local income = player:GetAttribute("Income") or 0
	local speed = player:GetAttribute("Speed") or 0
	cashLabel.Text = NumberFormat.cashLong(math.floor(cash))
	incomeLabel.Text = "+" .. NumberFormat.cash(income) .. "/s"
	speedLabel.Text = NumberFormat.commasShort(math.floor(speed))
	local nextArea = Economy.nextArea(speed)
	if nextArea then
		nextLabel.Text = "Next: " .. nextArea.name .. " (" .. NumberFormat.short(nextArea.speedRequired) .. " Speed)"
	else
		nextLabel.Text = "Every area unlocked!"
	end
end

local TOAST_COLORS = {
	good = Color3.fromRGB(90, 255, 90),
	bad = Color3.fromRGB(255, 80, 70),
	info = Color3.fromRGB(255, 255, 255),
}

function HUDController.toast(text, kind)
	if not text or text == "" then
		return
	end
	local label = UI.text(text, { size = UDim2.new(1, 0, 0, 36), color = TOAST_COLORS[kind] or TOAST_COLORS.info, stroke = 3, parent = toastHolder })
	task.delay(2.2, function()
		local fade = TweenInfo.new(0.3)
		TweenService:Create(label, fade, { TextTransparency = 1 }):Play()
		TweenService:Create(label.Outline, fade, { Transparency = 1 }):Play()
		task.wait(0.3)
		label:Destroy()
	end)
end

-- Big yellow area name at the bottom centre, like Steal An Egg's "HALLOWEEN EGG".
function HUDController.banner(text)
	banner.Text = string.upper(text)
	banner.Visible = true
	banner.TextTransparency = 0
	banner.Outline.Transparency = 0
	local token = {}
	HUDController.bannerToken = token
	task.delay(2.5, function()
		if HUDController.bannerToken ~= token then
			return
		end
		local fade = TweenInfo.new(0.4)
		TweenService:Create(banner, fade, { TextTransparency = 1 }):Play()
		TweenService:Create(banner.Outline, fade, { Transparency = 1 }):Play()
	end)
end

local function stepPop(gain, multiplier)
	local text = "+" .. NumberFormat.commasShort(math.floor(gain + 0.5)) .. " Speed"
	if multiplier and multiplier > 1 then
		text = text .. " (x" .. tostring(multiplier) .. ")"
	end
	local x = 0.5 + (math.random() - 0.5) * 0.14
	local label = UI.text(text, {
		anchor = Vector2.new(0.5, 0.5),
		position = UDim2.new(x, 0, 0.6, 0),
		size = UDim2.new(0, 300, 0, 40),
		stroke = 3,
		parent = popHolder,
	})
	UI.tint(label, UI.Tints.Cyan)
	local info = TweenInfo.new(0.9, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	TweenService:Create(label, info, { Position = UDim2.new(x, 0, 0.48, 0), TextTransparency = 1 }):Play()
	local fade = TweenService:Create(label.Outline, info, { Transparency = 1 })
	fade:Play()
	fade.Completed:Connect(function()
		label:Destroy()
	end)
end

-- Shows the area banner when you walk into a new area (or back into Town).
local function watchAreas()
	local current = nil
	task.spawn(function()
		while true do
			task.wait(0.3)
			local character = player.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root then
				local found = "Town"
				for _, bounds in ipairs(CollectionService:GetTagged("AreaBounds")) do
					if bounds:IsA("BasePart") then
						local p = bounds.CFrame:PointToObjectSpace(root.Position)
						local h = bounds.Size / 2
						if math.abs(p.X) <= h.X and math.abs(p.Y) <= h.Y and math.abs(p.Z) <= h.Z then
							found = bounds:GetAttribute("AreaName") or found
						end
					end
				end
				if found ~= current then
					if current ~= nil then
						HUDController.banner(found)
					end
					current = found
				end
			end
		end
	end)
end

function HUDController.start()
	build()
	for _, name in ipairs({ "Cash", "Income", "Speed" }) do
		player:GetAttributeChangedSignal(name):Connect(refresh)
	end
	refresh()
	Remotes:WaitForChild("Notify").OnClientEvent:Connect(HUDController.toast)
	Remotes:WaitForChild("TreadmillStep").OnClientEvent:Connect(stepPop)
	watchAreas()
end

return HUDController
]=])

install({ "StarterPlayer", "StarterPlayerScripts", "Controllers", "IncomePops" }, "ModuleScript", [=[
--[[
	IncomePops: Steal An Egg's "+$11" that floats up off every beast in YOUR pen each time
	the pen pays (GameConfig.Pen.IncomeTickSeconds). The amount is the beast model's "Income"
	attribute, set by RanchService.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local GameConfig = require(Shared:WaitForChild("GameConfig"))
local NumberFormat = require(Shared:WaitForChild("NumberFormat"))

local UI = require(script.Parent:WaitForChild("UI"))

local IncomePops = {}

local player = Players.LocalPlayer
local RISE = TweenInfo.new(0.9, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

local function pop(model)
	local body = model.PrimaryPart or model:FindFirstChild("Body")
	local income = model:GetAttribute("Income")
	if not body or not income or income <= 0 then
		return
	end
	local height = body.Size.Y
	local gui = Instance.new("BillboardGui")
	gui.Name = "IncomePop"
	gui.Size = UDim2.new(5, 0, 1.4, 0)
	gui.StudsOffsetWorldSpace = Vector3.new((math.random() - 0.5) * 1.5, height * 0.4, 0)
	gui.MaxDistance = 70
	gui.LightInfluence = 0
	gui.Adornee = body
	local label = Instance.new("TextLabel")
	label.BackgroundTransparency = 1
	label.Size = UDim2.new(1, 0, 1, 0)
	label.FontFace = UI.Font
	label.TextScaled = true
	label.Text = "+" .. NumberFormat.cashLong(income)
	label.TextColor3 = UI.Colors.CashGreen
	label.TextStrokeColor3 = Color3.new(0, 0, 0)
	label.TextStrokeTransparency = 0
	label.Parent = gui
	gui.Parent = body
	local start = gui.StudsOffsetWorldSpace
	TweenService:Create(gui, RISE, { StudsOffsetWorldSpace = start + Vector3.new(0, 3, 0) }):Play()
	local fade = TweenService:Create(label, RISE, { TextTransparency = 1, TextStrokeTransparency = 1 })
	fade:Play()
	fade.Completed:Connect(function()
		gui:Destroy()
	end)
end

function IncomePops.start()
	task.spawn(function()
		while true do
			task.wait(GameConfig.Pen.IncomeTickSeconds)
			local index = player:GetAttribute("PlotIndex")
			local runtime = workspace:FindFirstChild("Runtime")
			local pens = runtime and runtime:FindFirstChild("PenBeasts")
			local mine = index and pens and pens:FindFirstChild("Plot" .. index)
			if mine then
				for _, model in ipairs(mine:GetChildren()) do
					if model:IsA("Model") then
						pop(model)
					end
				end
			end
		end
	end)
end

return IncomePops
]=])

install({ "StarterPlayer", "StarterPlayerScripts", "Controllers", "ShopController" }, "ModuleScript", [=[
--[[
	ShopController: the Shop window, built exactly like the Check-UI kit's Shop menu
	(.claude/skills/check-ui-clean-roblox, examples/ShopMenuExample.luau; the user's reference
	picture is "Pasted image 20261020172519.png" in the vault):
	  * 600 x 415 solid slate-blue window (#3B5866) with a 3.5 px dark outline
	  * 60 px magenta-to-crimson header: pastel top line, fading damier, 2-tier divider,
	    "Shop" title on the left and the 3D beveled [X]
	  * "~Gamepass~" section: 276 x 155 cards (purple, cyan ...) with a sunburst, a fading damier,
	    the icon on the left, the description on the right and a lime Robux buy button
	  * "~Treadmills~", "~Spurs~" and "~Ranch~" sections: 180 x 175 lime product cards, three per
	    row, with the name on top, the icon in the middle and the price button at the bottom
	Opens from the left rail (Featured / Speed / Money jump to their section) or by stepping on
	the glowing ShopPad in Town. Buttons only ask the server (Remotes.Shop); cards update from
	player attributes.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local CollectionService = game:GetService("CollectionService")
local MarketplaceService = game:GetService("MarketplaceService")
local TweenService = game:GetService("TweenService")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local GameConfig = require(Shared:WaitForChild("GameConfig"))
local NumberFormat = require(Shared:WaitForChild("NumberFormat"))
local ShopRemote = ReplicatedStorage:WaitForChild("Remotes"):WaitForChild("Shop")

local UI = require(script.Parent:WaitForChild("UI"))

local ShopController = {}

local player = Players.LocalPlayer
local gui, window, list, uiScale
local sections = {}   -- [name] = section title label
local cards = {}      -- update functions, called with the player's cash
local busy = false
local toast = function() end

-- Check-UI card themes: gradient top/bottom, inner highlight, damier colour
local THEMES = {
	Purple = { Color3.fromRGB(235, 60, 255), Color3.fromRGB(150, 0, 245), Color3.fromRGB(235, 160, 255), Color3.fromRGB(90, 0, 165) },
	Cyan = { Color3.fromRGB(30, 235, 255), Color3.fromRGB(0, 120, 255), Color3.fromRGB(165, 240, 255), Color3.fromRGB(0, 65, 180) },
	Gold = { Color3.fromRGB(255, 220, 40), Color3.fromRGB(255, 140, 0), Color3.fromRGB(255, 240, 170), Color3.fromRGB(176, 96, 0) },
	Pink = { Color3.fromRGB(255, 60, 170), Color3.fromRGB(210, 0, 90), Color3.fromRGB(255, 176, 208), Color3.fromRGB(150, 0, 60) },
	Lime = { Color3.fromRGB(235, 255, 50), Color3.fromRGB(110, 215, 0), Color3.fromRGB(245, 255, 180), Color3.fromRGB(70, 170, 0) },
}
-- Pass card colours (GameConfig.Passes[].card) mapped onto the Check-UI themes
local PASS_THEMES = { Rainbow = "Purple", Gold = "Gold", Purple = "Pink", Blue = "Cyan" }

local function ask(action, arg)
	if busy then
		return
	end
	busy = true
	task.spawn(function()
		pcall(function()
			ShopRemote:InvokeServer(action, arg)
		end)
		busy = false
	end)
end

local function owns(spurId)
	return string.find("," .. (player:GetAttribute("OwnedSpurs") or "") .. ",", "," .. spurId .. ",", 1, true) ~= nil
end

----------------------------------------------------------------------------------------------
-- Building blocks (numbers from Check-UI's ShopMenuExample)
----------------------------------------------------------------------------------------------
local function sectionTitle(order, text)
	local label = UI.text("~" .. text .. "~", {
		name = "Section_" .. text,
		size = UDim2.new(1, 0, 0, 24),
		stroke = 2.6,
		parent = list,
	})
	label.LayoutOrder = order
	sections[text] = label
	return label
end

local function grid(order, cellW, cellH)
	return UI.new("Frame", {
		Name = "Grid",
		BackgroundTransparency = 1,
		LayoutOrder = order,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Parent = list,
	}, {
		UI.new("UIGridLayout", {
			CellSize = UDim2.new(0, cellW, 0, cellH),
			CellPadding = UDim2.new(0, 16, 0, 12),
			HorizontalAlignment = Enum.HorizontalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})
end

-- The card body every Check-UI card shares: white frame + gradient, black 2.8 px outline,
-- pastel inner line, fading damier and a sunburst.
local function cardBase(parent, order, name, theme, burstSize, burstPos, damierTile, damierFade, damierRotation)
	local frame = UI.new("Frame", {
		Name = name,
		LayoutOrder = order,
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		ClipsDescendants = true,
		ZIndex = 22,
		Parent = parent,
	}, { UI.corner(4), UI.border(2.8, Color3.new(0, 0, 0)) })
	UI.new("UIGradient", { Rotation = 90, Color = ColorSequence.new(theme[1], theme[2]), Parent = frame })
	local inner = UI.new("Frame", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(1, -6, 1, -6),
		ZIndex = 27,
		Parent = frame,
	}, { UI.corner(3) })
	UI.new("UIStroke", { Thickness = 1.4, Color = theme[3], ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = inner })
	UI.damier(frame, theme[4], damierTile, damierFade, 23, 0.35, damierRotation)
	UI.sunburst(frame, UDim2.new(0, burstSize, 0, burstSize), burstPos, 0.12, 24)
	return frame
end

-- ~Gamepass~ card (276 x 155): title on top, icon left, description right, Robux buy button
local function passCard(parent, order, pass)
	local theme = THEMES[PASS_THEMES[pass.card] or "Purple"]
	local frame = cardBase(parent, order, pass.name, theme, 220, UDim2.new(0, 68, 0.5, 12), 22,
		{ { 0, 1 }, { 0.35, 0.6 }, { 1, 0.05 } }, 65)
	UI.text(pass.name, { name = "Title", anchor = Vector2.new(0.5, 0), position = UDim2.new(0.5, 0, 0, 8),
		size = UDim2.new(1, -16, 0, 26), stroke = 2.8, z = 26, parent = frame })
	UI.icon(GameConfig.Icons[pass.icon], { anchor = Vector2.new(0, 0.5), position = UDim2.new(0, 8, 0.5, 12),
		size = UDim2.new(0, 120, 0, 95), z = 25, parent = frame })
	local description = UI.text(UI.highlight(pass.description), { name = "Description", rich = true,
		anchor = Vector2.new(0.5, 0.5), position = UDim2.new(0.72, 0, 0.46, 0), size = UDim2.new(0, 130, 0, 46),
		stroke = 2.4, z = 26, parent = frame })
	description.TextWrapped = true
	local price = UI.priceButton(NumberFormat.commas(pass.robux), true, {
		size = UDim2.new(0, 114, 0, 38),
		position = UDim2.new(0.72, 0, 0.78, 0),
		anchor = Vector2.new(0.5, 0.5),
		parent = frame,
	})
	price.ZIndex = 26
	price.Activated:Connect(function()
		if pass.gamePassId and pass.gamePassId > 0 then
			MarketplaceService:PromptGamePassPurchase(player, pass.gamePassId)
		else
			toast(pass.name .. " is coming soon!", "info")
		end
	end)
end

-- Product card (180 x 175): name on top, small line under it, icon in the middle, price button
local function productCard(parent, order, title, subtitle, icon)
	local frame = cardBase(parent, order, title, THEMES.Lime, 190, UDim2.new(0.5, 0, 0.5, 0), 18,
		{ { 0, 1 }, { 0.35, 0.65 }, { 1, 0.05 } }, 90)
	UI.text(title, { name = "Title", anchor = Vector2.new(0.5, 0), position = UDim2.new(0.5, 0, 0, 8),
		size = UDim2.new(1, -10, 0, 24), stroke = 2.8, z = 26, parent = frame })
	local sub = UI.text(UI.highlight(subtitle), { name = "Subtitle", rich = true, anchor = Vector2.new(0.5, 0),
		position = UDim2.new(0.5, 0, 0, 33), size = UDim2.new(1, -14, 0, 18), stroke = 2.2, z = 26, parent = frame })
	UI.icon(icon, { anchor = Vector2.new(0.5, 0.5), position = UDim2.new(0.5, 0, 0.5, 4),
		size = UDim2.new(0, 110, 0, 72), z = 25, parent = frame })
	local price = UI.priceButton("", false, {
		size = UDim2.new(1, -24, 0, 36),
		position = UDim2.new(0.5, 0, 1, -24),
		anchor = Vector2.new(0.5, 0.5),
		parent = frame,
	})
	price.ZIndex = 26
	return price, sub
end

-- Price button text + Check-UI state: lime "buy", cyan "equip", silver "owned", red "poor"
local function setButton(button, text, kind)
	button.Label.Text = text
	UI.setButtonState(button, kind)
end

----------------------------------------------------------------------------------------------
-- Sections
----------------------------------------------------------------------------------------------
local function buildPasses(order)
	local g = grid(order, 276, 155)
	for i, pass in ipairs(GameConfig.Passes) do
		passCard(g, i, pass)
	end
end

local function buildTreadmills(order)
	local g = grid(order, 180, 175)
	for i, t in ipairs(GameConfig.Treadmill.Tiers) do
		local price = productCard(g, i, t.name, "<green>+" .. NumberFormat.short(t.speedPerStep) .. "</green> Speed / step",
			GameConfig.Icons.Treadmill)
		price.Activated:Connect(function()
			ask("BuyTreadmill", t.tier)
		end)
		table.insert(cards, function(cash)
			local current = player:GetAttribute("TreadmillTier") or 1
			if t.tier == current then
				setButton(price, "Equipped", "owned")
			elseif t.tier < current then
				setButton(price, "Owned", "owned")
			elseif t.tier == current + 1 then
				setButton(price, NumberFormat.cash(t.price), cash >= t.price and "buy" or "poor")
			else
				setButton(price, "Locked", "owned")
			end
		end)
	end
end

local function buildSpurs(order)
	local g = grid(order, 180, 175)
	for i, spur in ipairs(GameConfig.Spurs) do
		local price = productCard(g, i, spur.name, "Treadmill <green>x" .. tostring(spur.multiplier) .. "</green>",
			GameConfig.Icons.Spurs)
		price.Activated:Connect(function()
			if player:GetAttribute("EquippedSpur") == spur.id then
				ask("EquipSpur", "")
			elseif owns(spur.id) then
				ask("EquipSpur", spur.id)
			else
				ask("BuySpur", spur.id)
			end
		end)
		table.insert(cards, function(cash)
			if player:GetAttribute("EquippedSpur") == spur.id then
				setButton(price, "Equipped", "owned")
			elseif owns(spur.id) then
				setButton(price, "Equip", "equip")
			else
				setButton(price, NumberFormat.cash(spur.price), cash >= spur.price and "buy" or "poor")
			end
		end)
	end
end

local function buildRanch(order)
	local g = grid(order, 180, 175)
	local price, sub = productCard(g, 1, "Pen Slot", "Room for <green>+1</green> beast", GameConfig.Icons.Pen)
	price.Activated:Connect(function()
		ask("BuyPenSlot")
	end)
	table.insert(cards, function(cash)
		local level = player:GetAttribute("PenLevel") or 1
		local slots = player:GetAttribute("PenSlots") or GameConfig.Pen.StartSlots
		local cost = GameConfig.Pen.UpgradePrices[level]
		if slots >= GameConfig.Pen.MaxSlots or not cost then
			setButton(price, "Maxed", "owned")
			sub.Text = UI.highlight("<green>" .. slots .. "</green> slots (max)")
		else
			setButton(price, NumberFormat.cash(cost), cash >= cost and "buy" or "poor")
			sub.Text = UI.highlight(slots .. " \u{2192} <green>" .. (slots + 1) .. "</green> slots")
		end
	end)
end

local function updateCards()
	if not window or not window.Visible then
		return
	end
	local cash = player:GetAttribute("Cash") or 0
	for _, update in ipairs(cards) do
		update(cash)
	end
end

----------------------------------------------------------------------------------------------
-- Window
----------------------------------------------------------------------------------------------
local function build()
	gui = UI.screen("Shop", 5)
	uiScale = UI.autoScale(gui, 1050, 620, 0.52, 1.18) -- Check-UI's responsive baseline

	window = UI.new("Frame", {
		Name = "ShopFrame",
		BackgroundColor3 = Color3.fromRGB(59, 88, 102),
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(0, 600, 0, 415),
		ClipsDescendants = true,
		Visible = false,
		ZIndex = 20,
		Parent = gui,
	}, { UI.corner(4), UI.border(3.5, Color3.fromRGB(24, 30, 34)) })

	-- Header: magenta -> crimson, pastel top line, fading damier, 2-tier divider
	local header = UI.new("Frame", {
		Name = "Header",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 60),
		ZIndex = 21,
		Parent = window,
	}, { UI.corner(4) })
	UI.new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.fromRGB(255, 20, 150), Color3.fromRGB(225, 0, 25)), Parent = header })
	UI.new("Frame", { Name = "TopHighlight", BackgroundColor3 = Color3.fromRGB(255, 200, 225), BackgroundTransparency = 0.3,
		BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 2), ZIndex = 22, Parent = header })
	UI.damier(header, Color3.fromRGB(150, 0, 20), 26, nil, 22, 0.35)
	UI.new("Frame", { Name = "DivDark", BackgroundColor3 = Color3.fromRGB(125, 0, 18), BorderSizePixel = 0,
		Position = UDim2.new(0, 0, 1, -6), Size = UDim2.new(1, 0, 0, 3), ZIndex = 23, Parent = header })
	UI.new("Frame", { Name = "DivBlack", BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0,
		Position = UDim2.new(0, 0, 1, -3), Size = UDim2.new(1, 0, 0, 3), ZIndex = 23, Parent = header })
	UI.text("Shop", {
		name = "Title",
		align = "Left",
		anchor = Vector2.new(0, 0.5),
		position = UDim2.new(0, 18, 0.5, -2),
		size = UDim2.new(0, 180, 0, 44),
		stroke = 3.2,
		z = 24,
		parent = header,
	})
	local close = UI.closeButton(header)
	close.Size = UDim2.new(0, 38, 0, 38)
	close.AnchorPoint = Vector2.new(0.5, 0.5)
	close.Position = UDim2.new(1, -34, 0.5, -2)
	close.ZIndex = 25
	close.Activated:Connect(function()
		ShopController.close()
	end)

	list = UI.new("ScrollingFrame", {
		Name = "ContentScroll",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.new(0, 0, 0, 60),
		Size = UDim2.new(1, 0, 1, -60),
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 7,
		ScrollBarImageColor3 = Color3.fromRGB(210, 225, 235),
		ScrollBarImageTransparency = 0.3,
		ZIndex = 21,
		Parent = window,
	}, {
		UI.new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
			HorizontalAlignment = Enum.HorizontalAlignment.Center }),
		UI.new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 14) }),
	})

	sectionTitle(1, "Gamepass")
	buildPasses(2)
	sectionTitle(3, "Treadmills")
	buildTreadmills(4)
	sectionTitle(5, "Spurs")
	buildSpurs(6)
	sectionTitle(7, "Ranch")
	buildRanch(8)
end

-- section: "Gamepass" (top), "Treadmills", "Spurs" or "Ranch"
function ShopController.open(section)
	window.Visible = true
	updateCards()
	local title = sections[section or "Gamepass"]
	if title then
		task.defer(function()
			local scale = uiScale and uiScale.Scale or 1
			local y = (title.AbsolutePosition.Y - list.AbsolutePosition.Y) / scale + list.CanvasPosition.Y
			list.CanvasPosition = Vector2.new(0, math.max(0, y - 6))
		end)
	end
	-- Check-UI pop-in: centred scale from 0.85 with Back easing
	local pop = window:FindFirstChild("WindowScale") or UI.new("UIScale", { Name = "WindowScale", Parent = window })
	pop.Scale = 0.85
	TweenService:Create(pop, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
end

function ShopController.close()
	window.Visible = false
end

function ShopController.toggle(section)
	if window.Visible then
		ShopController.close()
	else
		ShopController.open(section)
	end
end

-- Opens the shop once each time you step onto a ShopPad (not every frame you stand on it).
local function watchPads()
	local wasOn = false
	RunService.Heartbeat:Connect(function()
		local character = player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local on = false
		for _, pad in ipairs(CollectionService:GetTagged("ShopPad")) do
			if pad:IsA("BasePart") then
				local offset = root.Position - pad.Position
				local flat = Vector3.new(offset.X, 0, offset.Z).Magnitude
				if flat <= pad.Size.Y / 2 and math.abs(offset.Y) < 8 then
					on = true
				end
			end
		end
		if on and not wasOn then
			ShopController.open("Gamepass")
		end
		wasOn = on
	end)
end

-- Which prices the player can afford, as a string (it only changes when a button would)
local function affordKey(cash)
	local bits = {}
	for _, t in ipairs(GameConfig.Treadmill.Tiers) do
		table.insert(bits, cash >= t.price and "1" or "0")
	end
	for _, spur in ipairs(GameConfig.Spurs) do
		table.insert(bits, cash >= spur.price and "1" or "0")
	end
	for _, price in ipairs(GameConfig.Pen.UpgradePrices) do
		table.insert(bits, cash >= price and "1" or "0")
	end
	return table.concat(bits)
end

function ShopController.start(hud)
	build()
	if hud then
		toast = hud.toast
		local rail = hud.railButtons or {}
		local jumps = { Featured = "Gamepass", Speed = "Treadmills", Money = "Ranch" }
		for name, section in pairs(jumps) do
			if rail[name] then
				rail[name].Activated:Connect(function()
					ShopController.open(section)
				end)
			end
		end
		if rail.Index then
			rail.Index.Activated:Connect(function()
				toast("The Beast Index is coming soon!", "info")
			end)
		end
	end
	for _, name in ipairs({ "TreadmillTier", "OwnedSpurs", "EquippedSpur", "PenLevel", "PenSlots" }) do
		player:GetAttributeChangedSignal(name):Connect(updateCards)
	end
	local lastKey = nil
	player:GetAttributeChangedSignal("Cash"):Connect(function()
		local key = affordKey(player:GetAttribute("Cash") or 0)
		if key ~= lastKey then
			lastKey = key
			updateCards()
		end
	end)
	watchPads()
end

return ShopController
]=])

install({ "StarterPlayer", "StarterPlayerScripts", "Controllers", "UI" }, "ModuleScript", [=[
--[[
	UI: the style kit, copied from Steal An Egg's real UI (screenshots in the vault note
	"Roblox Research/Concepts/UI Style Guide.md").

	* One font everywhere: Montserrat Black. Roblox ships it as the Gotham family
	  (Enum.Font.GothamBlack = GothamSSm, weight Heavy). The cash counter uses the italic face.
	* White text with a thick black outline. Coloured text is white with a vertical UIGradient
	  (white on top, tint at the bottom), so the black outline stays black.
	* Lime-green price buttons, a red square close button, a green window header with a light
	  diagonal shine, and a dark grey window body.

	Sizes are in pixels for a 1280 x 720 screen. Each ScreenGui gets a UIScale (UI.autoScale),
	so phones and big monitors see the same layout.

	Components from the Check-UI kit (MIT, .claude/skills/check-ui-clean-roblox, game/vendor/CheckUI):
	the 3D beveled buy and close buttons, damier (checkerboard) overlays, rotating sunbursts and
	its uploaded icons (GameConfig.Icons, each with an emoji fallback if the image fails to load).
]]

local Players = game:GetService("Players")
local ContentProvider = game:GetService("ContentProvider")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local GameConfig = require(ReplicatedStorage:WaitForChild("Shared"):WaitForChild("GameConfig"))

local UI = {}

local FAMILY = "rbxasset://fonts/families/GothamSSm.json"
UI.Font = Font.new(FAMILY, Enum.FontWeight.Heavy, Enum.FontStyle.Normal)
UI.FontItalic = Font.new(FAMILY, Enum.FontWeight.Heavy, Enum.FontStyle.Italic)
UI.FontBold = Font.new(FAMILY, Enum.FontWeight.Bold, Enum.FontStyle.Normal)

UI.Colors = {
	Outline = Color3.fromRGB(0, 0, 0),
	White = Color3.fromRGB(255, 255, 255),
	CashGreen = Color3.fromRGB(24, 255, 24),      -- the "$43,931" counter
	HighlightGreen = Color3.fromRGB(40, 230, 40), -- "x2" inside descriptions
	SpeedBlue = Color3.fromRGB(70, 215, 255),
	HeaderTop = Color3.fromRGB(140, 236, 70),
	HeaderBottom = Color3.fromRGB(86, 200, 30),
	HeaderBorder = Color3.fromRGB(40, 110, 20),
	Body = Color3.fromRGB(58, 59, 66),
	BodyBorder = Color3.fromRGB(30, 30, 34),
	CardBorder = Color3.fromRGB(28, 28, 30),
	Grey = Color3.fromRGB(110, 110, 116),
	Red = Color3.fromRGB(255, 70, 60),
}

-- Bottom tints for gradient text (top is always white)
UI.Tints = {
	Featured = { Color3.fromRGB(255, 236, 110), Color3.fromRGB(255, 170, 30) }, -- yellow -> orange, both ends tinted
	Gold = { Color3.fromRGB(255, 250, 150), Color3.fromRGB(255, 200, 0) },      -- "-- FEATURED --" / "-- PASSES --"
	Cyan = { Color3.fromRGB(170, 250, 255), Color3.fromRGB(0, 200, 255) },      -- "-- SPEED --"
	Green = { Color3.fromRGB(255, 255, 255), Color3.fromRGB(150, 255, 150) },   -- "Money" label
	Blue = { Color3.fromRGB(255, 255, 255), Color3.fromRGB(130, 240, 255) },    -- "Speed" label
	Peach = { Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 205, 140) },   -- "Stars" label
}

UI.Rainbow = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 60, 60)),
	ColorSequenceKeypoint.new(0.2, Color3.fromRGB(255, 160, 30)),
	ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 240, 60)),
	ColorSequenceKeypoint.new(0.6, Color3.fromRGB(80, 230, 90)),
	ColorSequenceKeypoint.new(0.8, Color3.fromRGB(60, 170, 255)),
	ColorSequenceKeypoint.new(1, Color3.fromRGB(190, 80, 255)),
})

function UI.new(className, props, children)
	local instance = Instance.new(className)
	local parent = nil
	for key, value in pairs(props or {}) do
		if key == "Parent" then
			parent = value
		else
			instance[key] = value
		end
	end
	for _, child in ipairs(children or {}) do
		child.Parent = instance
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

function UI.corner(radius)
	return UI.new("UICorner", { CornerRadius = UDim.new(0, radius or 6) })
end

-- A border stroke for frames and buttons
function UI.border(thickness, color)
	return UI.new("UIStroke", {
		Thickness = thickness or 3,
		Color = color or UI.Colors.Outline,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		LineJoinMode = Enum.LineJoinMode.Round,
	})
end

--[[ Outlined text.
	opts: size (UDim2), position, anchor, color, stroke (px), italic, align ("Left"/"Center"/"Right"),
	      rich (RichText), maxSize (TextSize cap), z, name, parent ]]
function UI.text(text, opts)
	opts = opts or {}
	local label = UI.new("TextLabel", {
		Name = opts.name or "Text",
		BackgroundTransparency = 1,
		FontFace = opts.italic and UI.FontItalic or UI.Font,
		Text = text,
		TextScaled = true,
		RichText = opts.rich == true,
		TextColor3 = opts.color or UI.Colors.White,
		TextXAlignment = Enum.TextXAlignment[opts.align or "Center"],
		Size = opts.size or UDim2.new(1, 0, 1, 0),
		Position = opts.position or UDim2.new(0, 0, 0, 0),
		AnchorPoint = opts.anchor or Vector2.new(0, 0),
		ZIndex = opts.z or 2,
	})
	UI.new("UIStroke", {
		Name = "Outline",
		Thickness = opts.stroke or 3,
		Color = UI.Colors.Outline,
		LineJoinMode = Enum.LineJoinMode.Round,
		Parent = label,
	})
	if opts.maxSize then
		UI.new("UITextSizeConstraint", { MaxTextSize = opts.maxSize, Parent = label })
	end
	if opts.parent then
		label.Parent = opts.parent
	end
	return label
end

-- White-to-tint vertical gradient on a text label (the outline stays black).
function UI.tint(label, tint)
	local gradient = label:FindFirstChildOfClass("UIGradient") or UI.new("UIGradient", { Parent = label })
	gradient.Rotation = 90
	gradient.Color = ColorSequence.new(tint[1], tint[2])
	return gradient
end

function UI.rainbow(label)
	local gradient = label:FindFirstChildOfClass("UIGradient") or UI.new("UIGradient", { Parent = label })
	gradient.Rotation = 0
	gradient.Color = UI.Rainbow
	return gradient
end

-- Light diagonal stripes like the shop header's glass shine.
function UI.shine(frame, transparency)
	local holder = UI.new("Frame", {
		Name = "Shine",
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Size = UDim2.new(1, 0, 1, 0),
		ZIndex = frame.ZIndex,
		Parent = frame,
	})
	for i, x in ipairs({ 0.42, 0.5, 0.78 }) do
		UI.new("Frame", {
			BackgroundColor3 = UI.Colors.White,
			BackgroundTransparency = transparency or 0.8,
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(x, 0, 0.5, 0),
			Size = UDim2.new(0, i == 2 and 10 or 26, 3, 0),
			Rotation = 35,
			ZIndex = frame.ZIndex,
			Parent = holder,
		})
	end
	return holder
end

-- Rich text helper: "Get <green>x2</green> Money!" -> RichText with the highlight colour.
function UI.highlight(text)
	local hex = string.format("#%02X%02X%02X", 40, 230, 40)
	return (string.gsub(text, "<green>(.-)</green>", '<font color="' .. hex .. '">%1</font>'))
end

-- Grow a little on hover, squash on press (UI Patterns: 1.0 -> 1.08 -> 0.95).
function UI.pressable(button)
	local scale = button:FindFirstChildOfClass("UIScale") or UI.new("UIScale", { Parent = button })
	local TweenService = game:GetService("TweenService")
	local info = TweenInfo.new(0.08)
	local function to(value)
		TweenService:Create(scale, info, { Scale = value }):Play()
	end
	button.MouseEnter:Connect(function()
		to(1.06)
	end)
	button.MouseLeave:Connect(function()
		to(1)
	end)
	button.MouseButton1Down:Connect(function()
		to(0.94)
	end)
	button.MouseButton1Up:Connect(function()
		to(1.06)
	end)
end

-- Check-UI button states: { top, bottom, bevel, highlight, damier }
UI.ButtonStates = {
	buy = { Color3.fromRGB(235, 255, 30), Color3.fromRGB(20, 215, 10), Color3.fromRGB(15, 120, 15), Color3.fromRGB(235, 255, 130), Color3.fromRGB(0, 110, 0) },
	owned = { Color3.fromRGB(216, 222, 228), Color3.fromRGB(148, 160, 176), Color3.fromRGB(72, 82, 96), Color3.fromRGB(255, 255, 255), Color3.fromRGB(96, 104, 112) },
	poor = { Color3.fromRGB(255, 32, 80), Color3.fromRGB(208, 0, 32), Color3.fromRGB(112, 0, 16), Color3.fromRGB(255, 176, 200), Color3.fromRGB(144, 0, 24) },
	equip = { Color3.fromRGB(0, 205, 255), Color3.fromRGB(0, 130, 245), Color3.fromRGB(0, 50, 110), Color3.fromRGB(180, 240, 255), Color3.fromRGB(0, 75, 150) },
	gift = { Color3.fromRGB(196, 80, 255), Color3.fromRGB(140, 30, 220), Color3.fromRGB(70, 10, 110), Color3.fromRGB(230, 180, 255), Color3.fromRGB(96, 0, 144) },
}

-- Checkerboard overlay (Check-UI "damier"): the uploaded 2x2 checker tile, tinted, fading in
-- toward the bottom. tile = pixels per tile. fade = { top, bottom } transparencies, or a list of
-- { position, transparency } keypoints (Check-UI's 4-point fade is the default).
UI.DAMIER_FADE = { { 0, 1 }, { 0.3, 0.82 }, { 0.65, 0.35 }, { 1, 0.1 } }
function UI.damier(parent, color, tile, fade, z, imageTransparency, rotation)
	local layer = UI.new("ImageLabel", {
		Name = "Damier",
		BackgroundTransparency = 1,
		Image = GameConfig.UIAssets.Checker,
		ImageColor3 = color or Color3.new(0, 0, 0),
		ImageTransparency = imageTransparency or 0,
		ScaleType = Enum.ScaleType.Tile,
		TileSize = UDim2.new(0, tile or 18, 0, tile or 18),
		Size = UDim2.new(1, 0, 1, 0),
		ZIndex = z or parent.ZIndex,
		Parent = parent,
	})
	fade = fade or UI.DAMIER_FADE
	local sequence
	if type(fade[1]) == "table" then
		local points = {}
		for _, kp in ipairs(fade) do
			table.insert(points, NumberSequenceKeypoint.new(kp[1], kp[2]))
		end
		sequence = NumberSequence.new(points)
	else
		sequence = NumberSequence.new(fade[1], fade[2])
	end
	UI.new("UIGradient", { Rotation = rotation or 90, Transparency = sequence, Parent = layer })
	return layer
end

-- Rotating sunburst behind an icon (Check-UI: 20 degrees per second, only while visible)
local sunbursts = {}
function UI.sunburst(parent, size, position, transparency, z)
	local burst = UI.new("ImageLabel", {
		Name = "Sunburst",
		BackgroundTransparency = 1,
		Image = GameConfig.UIAssets.Sunburst,
		ImageTransparency = transparency or 0.45,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = position,
		Size = size,
		SizeConstraint = Enum.SizeConstraint.RelativeYY,
		ZIndex = z or parent.ZIndex,
		Parent = parent,
	})
	table.insert(sunbursts, burst)
	return burst
end
RunService.RenderStepped:Connect(function(dt)
	for i = #sunbursts, 1, -1 do
		local burst = sunbursts[i]
		if not burst.Parent then
			table.remove(sunbursts, i)
		elseif burst.Visible then
			burst.Rotation = (burst.Rotation + 20 * dt) % 360
		end
	end
end)

-- Check-UI 3D button: gradient face, 3px dark bevel along the bottom, pastel inner highlight,
-- checker overlay and a 3px near-black border. state = a key of UI.ButtonStates.
function UI.bevelButton(opts)
	local button = UI.new("TextButton", {
		Name = opts.name or "Button",
		Text = "",
		AutoButtonColor = false,
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Size = opts.size,
		Position = opts.position or UDim2.new(0, 0, 0, 0),
		AnchorPoint = opts.anchor or Vector2.new(0, 0),
		ZIndex = opts.z or 3,
	}, { UI.corner(4), UI.border(2.4, Color3.new(0, 0, 0)) })
	UI.new("UIGradient", { Name = "Face", Rotation = 90, Parent = button })
	UI.new("Frame", {
		Name = "Bevel",
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 0, 1, 0),
		Size = UDim2.new(1, 0, 0, 3),
		ZIndex = button.ZIndex,
		Parent = button,
	})
	UI.damier(button, Color3.new(0, 0, 0), 12, nil, button.ZIndex)
	local inner = UI.new("Frame", {
		Name = "Inner",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, -1),
		Size = UDim2.new(1, -4, 1, -6),
		ZIndex = button.ZIndex,
		Parent = button,
	}, { UI.corner(3) })
	UI.new("UIStroke", { Name = "Highlight", Thickness = 1.2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = inner })
	UI.setButtonState(button, opts.state or "buy")
	UI.pressable(button)
	if opts.parent then
		button.Parent = opts.parent
	end
	return button
end

function UI.setButtonState(button, state)
	local colors = UI.ButtonStates[state] or UI.ButtonStates.buy
	local face = button:FindFirstChild("Face")
	if face then
		face.Color = ColorSequence.new(colors[1], colors[2])
	end
	local bevel = button:FindFirstChild("Bevel")
	if bevel then
		bevel.BackgroundColor3 = colors[3]
	end
	local inner = button:FindFirstChild("Inner")
	local highlight = inner and inner:FindFirstChild("Highlight")
	if highlight then
		highlight.Color = colors[4]
	end
	local damier = button:FindFirstChild("Damier")
	if damier then
		damier.ImageColor3 = colors[5]
	end
end

-- Lime buy button with an optional Robux icon and the price ("467").
function UI.priceButton(text, robux, opts)
	opts = opts or {}
	local button = UI.bevelButton({
		name = "Price",
		state = opts.state or "buy",
		size = opts.size,
		position = opts.position,
		anchor = opts.anchor,
		parent = opts.parent,
	})
	local x = 0.06
	if robux then
		UI.icon(GameConfig.Icons.Robux, {
			name = "Robux",
			anchor = Vector2.new(0, 0.5),
			position = UDim2.new(0.1, 0, 0.5, -1),
			size = UDim2.new(0.62, 0, 0.62, 0),
			square = true,
			z = button.ZIndex + 1,
			parent = button,
		})
		x = 0.3
	end
	UI.text(text, {
		name = "Label",
		size = UDim2.new(1 - x - 0.06, 0, 0.68, 0),
		position = UDim2.new(x, 0, 0.13, 0),
		stroke = 2.5,
		z = button.ZIndex + 1,
		parent = button,
	})
	return button
end

-- Check-UI's 3D beveled square close button: burgundy base, crimson-pink face shifted up 4px,
-- pastel inner line, white X.
function UI.closeButton(parent)
	local button = UI.new("TextButton", {
		Name = "Close",
		Text = "",
		AutoButtonColor = false,
		BackgroundColor3 = Color3.fromRGB(115, 0, 16),
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		Size = UDim2.new(0, 46, 0, 46),
		ZIndex = 4,
	}, { UI.border(2.8, Color3.new(0, 0, 0)) })
	local face = UI.new("Frame", {
		Name = "Face",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, -4),
		ZIndex = 5,
		Parent = button,
	})
	UI.new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.fromRGB(255, 125, 175), Color3.fromRGB(255, 20, 40)), Parent = face })
	local inner = UI.new("Frame", {
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(1, -3, 1, -3),
		ZIndex = 6,
		Parent = face,
	})
	UI.new("UIStroke", { Thickness = 1.2, Color = Color3.fromRGB(255, 210, 235), ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = inner })
	UI.new("Frame", {
		BackgroundColor3 = Color3.fromRGB(70, 0, 10),
		BorderSizePixel = 0,
		Position = UDim2.new(0, 0, 1, -4),
		Size = UDim2.new(1, 0, 0, 1),
		ZIndex = 6,
		Parent = button,
	})
	UI.text("X", { size = UDim2.new(0.72, 0, 0.72, 0), position = UDim2.new(0.14, 0, 0.12, 0), stroke = 3, z = 7, parent = face })
	UI.pressable(button)
	button.Parent = parent
	return button
end

local function emojiLabel(emoji, opts)
	return UI.new("TextLabel", {
		Name = opts.name or "Icon",
		BackgroundTransparency = 1,
		Text = emoji,
		TextScaled = true,
		FontFace = UI.Font,
		TextColor3 = UI.Colors.White,
		Size = opts.size,
		Position = opts.position or UDim2.new(0, 0, 0, 0),
		AnchorPoint = opts.anchor or Vector2.new(0, 0),
		SizeConstraint = opts.square and Enum.SizeConstraint.RelativeYY or Enum.SizeConstraint.RelativeXY,
		ZIndex = opts.z or 2,
		Parent = opts.parent,
	})
end

--[[ An icon. icon = { image = "rbxassetid://...", emoji = "..." } (GameConfig.Icons), a plain
	"rbxassetid://..." string, or an emoji string. Images keep their shape (ScaleType Fit, as
	Check-UI requires); if one fails to load, the emoji takes its place. ]]
function UI.icon(icon, opts)
	local image, emoji = nil, nil
	if type(icon) == "table" then
		image, emoji = icon.image, icon.emoji
	elseif type(icon) == "string" and string.sub(icon, 1, 13) == "rbxassetid://" then
		image = icon
	else
		emoji = icon
	end
	if not image then
		return emojiLabel(emoji or "?", opts)
	end
	local label = UI.new("ImageLabel", {
		Name = opts.name or "Icon",
		BackgroundTransparency = 1,
		Image = image,
		ScaleType = Enum.ScaleType.Fit,
		Size = opts.size,
		Position = opts.position or UDim2.new(0, 0, 0, 0),
		AnchorPoint = opts.anchor or Vector2.new(0, 0),
		SizeConstraint = opts.square and Enum.SizeConstraint.RelativeYY or Enum.SizeConstraint.RelativeXY,
		ZIndex = opts.z or 2,
		Parent = opts.parent,
	})
	if emoji then
		task.spawn(function()
			local ok = pcall(function()
				ContentProvider:PreloadAsync({ label }, function(_, status)
					if status ~= Enum.AssetFetchStatus.Success and label.Parent then
						local fallback = emojiLabel(emoji, opts)
						fallback.Parent = label.Parent
						label:Destroy()
					end
				end)
			end)
			if not ok then
				warn("[UI] could not preload icon " .. image)
			end
		end)
	end
	return label
end

-- Keeps a layout the same size relative to any screen. Default baseline 1280x720; the Check-UI
-- windows use theirs (1050x620, clamped 0.52-1.18).
function UI.autoScale(screenGui, baseX, baseY, minScale, maxScale)
	local scale = UI.new("UIScale", { Parent = screenGui })
	local camera = workspace.CurrentCamera
	local function update()
		local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
		scale.Scale = math.clamp(math.min(viewport.X / (baseX or 1280), viewport.Y / (baseY or 720)), minScale or 0.55, maxScale or 1.6)
	end
	update()
	if camera then
		camera:GetPropertyChangedSignal("ViewportSize"):Connect(update)
	end
	return scale
end

function UI.screen(name, order)
	return UI.new("ScreenGui", {
		Name = name,
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		DisplayOrder = order or 0,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		Parent = Players.LocalPlayer:WaitForChild("PlayerGui"),
	})
end

return UI
]=])

